function searchLines(library, text) {
  let results = [];
  for (let isbn in library) {
    if (library[isbn].title.includes(text)) {
      results.push(`${isbn}: ${library[isbn].title}`);
    }
  }
  return results.join('\n');
}

module.exports = {
  shelfLine,
  availability,
  memberLine,
  makeLookup,
  overdueLines,
  fineReport,
  canBorrow,
  snapshot,
  restore,
  searchLines
};

